"use strict";(self.webpackChunkliquidflashcards_docs=self.webpackChunkliquidflashcards_docs||[]).push([[5754],{2899(e){e.exports=JSON.parse('{"tag":{"label":"decision","permalink":"/liquidflashcards-docs/decisions/tags/decision","allTagsPath":"/liquidflashcards-docs/decisions/tags","count":11,"items":[{"id":"0001-one-global-card-library","title":"ADR 0001: One global card library with deck links","description":"Cards belong to the profile, not to a deck; decks reference them through a many-to-many DeckCardLink, and each card keeps one review schedule.","permalink":"/liquidflashcards-docs/decisions/0001-one-global-card-library"},{"id":"0002-fsrs-scheduling","title":"ADR 0002: FSRS scheduling through swift-fsrs, replacing SM-2","description":"Reviews are scheduled with FSRS-6 from the swift-fsrs package behind an app-owned adapter; the original SM-2 engine was removed.","permalink":"/liquidflashcards-docs/decisions/0002-fsrs-scheduling"},{"id":"0003-swiftdata-with-opt-in-cloudkit","title":"ADR 0003: SwiftData with opt-in CloudKit mirroring and versioned schemas","description":"All data lives in one SwiftData store that mirrors to the iCloud private database only when the user turns sync on; schema changes go through AppSchemaVn versions and the store is never deleted while it holds data.","permalink":"/liquidflashcards-docs/decisions/0003-swiftdata-with-opt-in-cloudkit"},{"id":"0004-profile-delete-keeps-content","title":"ADR 0004: Deleting a profile nullifies its decks and cards","description":"Profile.decks and Profile.cards use a nullify delete rule, and startup maintenance adopts profile-less decks and cards, so a synced profile merge can\'t delete another device\'s offline content.","permalink":"/liquidflashcards-docs/decisions/0004-profile-delete-keeps-content"},{"id":"0005-fsrs-local-day-frame","title":"ADR 0005: FSRS dates in the learner\'s local-day frame","description":"FSRSEngine shifts every date by the learner\'s UTC offset before calling swift-fsrs and back afterwards, so elapsed days roll over at local midnight, not UTC midnight.","permalink":"/liquidflashcards-docs/decisions/0005-fsrs-local-day-frame"},{"id":"0006-mvvm-services-and-l10n","title":"ADR 0006: MVVM plus services, with every string through L10n","description":"Views talk to @Observable view models, view models call services that own all SwiftData mutations, and user-facing text goes through typed L10n accessors over the string catalog.","permalink":"/liquidflashcards-docs/decisions/0006-mvvm-services-and-l10n"},{"id":"0007-pm-replaces-bmad","title":"ADR 0007: Track work in pm instead of BMAD planning","description":"Work was tracked as Markdown tasks with a gated pipeline, a board and Claude Code hooks (the pm tool); the BMAD planning artifacts were kept read-only as history. Superseded by ADR 0010.","permalink":"/liquidflashcards-docs/decisions/0007-pm-replaces-bmad"},{"id":"0008-native-visionos","title":"ADR 0008: A native visionOS app from the shared codebase","description":"Vision Pro gets a native visionOS destination of the same app target (not the Designed-for-iPad build), with minimum visionOS 26 and the native visionOS design language applied at the shared chrome layer.","permalink":"/liquidflashcards-docs/decisions/0008-native-visionos"},{"id":"0009-palettes-map-from-plum","title":"ADR 0009: Palettes are a generated mapping from plum","description":"The six colour palettes aren\'t separate token sets; AppColors stays written in plum and a generated table maps each plum colour to the chosen palette at run time.","permalink":"/liquidflashcards-docs/decisions/0009-palettes-map-from-plum"},{"id":"0010-superpowers-replaces-pm","title":"ADR 0010: Superpowers replaces pm","description":"Work follows the superpowers flow (brainstorm, spec and plan in docs/superpowers/, TDD, review, verify) instead of the pm task pipeline, and the docs are published as a site that the update-docs-site skill refreshes after merges.","permalink":"/liquidflashcards-docs/decisions/0010-superpowers-replaces-pm"},{"id":"README","title":"Decisions","description":"Index of the architecture decision records (ADRs) that shape the app, and when and how to add a new one.","permalink":"/liquidflashcards-docs/decisions/"}],"unlisted":false}}')}}]);